fun decimal(value: Int): String {
    if (value < 0) { error("negative count") }
    val digit = when {
        value % 10 == 0 -> "0"
        value % 10 == 1 -> "1"
        value % 10 == 2 -> "2"
        value % 10 == 3 -> "3"
        value % 10 == 4 -> "4"
        value % 10 == 5 -> "5"
        value % 10 == 6 -> "6"
        value % 10 == 7 -> "7"
        value % 10 == 8 -> "8"
        else -> "9"
    }
    val prefix = if (value >= 10) { decimal(value / 10) } else { "" }
    return prefix + digit
}

